import { createClient } from "@/lib/supabase/server";
import DashboardCharts from "./DashboardCharts";
import PanelInfo from "@/app/admin/components/PanelInfo";
import BackButton from "@/app/admin/components/BackButton"; // <--- 1. Importas el botón aquí

function KpiCard({ label, value, hint }: { label: string; value: string | number; hint?: string }) {
  return (
    <div className="bg-white/5 border border-white/10 rounded-lg p-5">
      <p className="text-sm text-white/50">{label}</p>
      <p className="text-3xl font-bold text-gold mt-1">{value}</p>
      {hint && <p className="text-xs text-white/40 mt-1">{hint}</p>}
    </div>
  );
}

export default async function AdminDashboardPage() {
  const supabase = await createClient();
  const nowIso = new Date().toISOString();
  const sieteDiasAtras = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

  // Todas las consultas de KPIs en paralelo, no una tras otra
  const [
    { count: clasesActivas },
    { count: totalUsuarios },
    { count: usuariosNuevos },
    { count: totalTestimonios },
    { count: testimoniosPendientes },
    { count: cursosPublicados },
    { count: patrocinadoresActivos },
    { data: weeklySignups },
    { data: topEventos },
    { data: topAcciones },
  ] = await Promise.all([
    supabase.from("events").select("*", { count: "exact", head: true })
      .eq("status", "published").gte("end_time", nowIso),
    supabase.from("profiles").select("*", { count: "exact", head: true }),
    supabase.from("profiles").select("*", { count: "exact", head: true })
      .gte("created_at", sieteDiasAtras),
    supabase.from("testimonials").select("*", { count: "exact", head: true }),
    supabase.from("testimonials").select("*", { count: "exact", head: true })
      .eq("status", "pending"),
    supabase.from("courses").select("*", { count: "exact", head: true })
      .eq("status", "published"),
    supabase.from("sponsors").select("*", { count: "exact", head: true })
      .eq("active", true),
    supabase.from("weekly_signups").select("week, total").order("week", { ascending: true }).limit(8),
    supabase.from("event_attendance_counts").select("title, total_registered")
      .order("total_registered", { ascending: false }).limit(5),
    supabase.from("top_actions_last_30_days").select("action, total").limit(8),
  ]);

  return (
    <div>
      <BackButton /> {/* <--- 2. Lo pones aquí arriba para que aparezca la flecha */}

      <h1 className="text-2xl font-bold mb-6">Dashboard</h1>

      <PanelInfo
        title="¿Para qué sirve este panel?"
        description="Muestra métricas clave del sitio: clases activas, usuarios totales y nuevos, comentarios pendientes de moderar, y gráficas de tendencia (usuarios nuevos por semana, clases con más inscritos, interacciones más frecuentes). Se actualiza en tiempo real con cada visita."
      />

      {/* KPIs principales */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-10">
        <KpiCard label="Clases activas" value={clasesActivas ?? 0} />
        <KpiCard label="Usuarios totales" value={totalUsuarios ?? 0} hint={`+${usuariosNuevos ?? 0} en 7 días`} />
        <KpiCard label="Comentarios" value={totalTestimonios ?? 0} hint={`${testimoniosPendientes ?? 0} por revisar`} />
        <KpiCard label="Cursos publicados" value={cursosPublicados ?? 0} />
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-10">
        <KpiCard label="Patrocinadores activos" value={patrocinadoresActivos ?? 0} />
      </div>

      {testimoniosPendientes && testimoniosPendientes > 0 && (
        <div className="bg-gold/10 border border-gold/30 rounded-lg p-4 mb-10 text-sm">
          Tienes <strong>{testimoniosPendientes}</strong> testimonio(s) esperando moderación en{" "}
          <a href="/admin/interaccion" className="underline text-gold">Interacción</a>.
        </div>
      )}

      {/* Gráficas (requieren cliente) */}
      <DashboardCharts
        weeklySignups={weeklySignups ?? []}
        topEventos={topEventos ?? []}
        topAcciones={topAcciones ?? []}
      />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import CategorySelect from "./nuevo/CategorySelect";
import { createEvent } from "./actions";

type Category = { id: string; name: string };

export default function ClaseOnlineModal({
  categories = [],
}: {
  categories: Category[];
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [mounted, setMounted] = useState(false);
  const [startValue, setStartValue] = useState("");

  useEffect(() => {
    setMounted(true);
  }, []);

  const nowIso = new Date(Date.now() - new Date().getTimezoneOffset() * 60000)
    .toISOString()
    .slice(0, 16);

  const handleSubmit = async (formData: FormData) => {
    setIsSubmitting(true);
    await createEvent(formData);
    setIsSubmitting(false);
    setIsOpen(false);
  };

  const modalContent = isOpen ? (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-md p-3 sm:p-4 overflow-y-auto">
      <div className="relative my-auto w-full max-w-xl rounded-2xl border border-cyan-500/30 bg-[#0d0d10] p-5 sm:p-7 shadow-2xl max-h-[90vh] overflow-y-auto text-white">
        <button
          type="button"
          onClick={() => setIsOpen(false)}
          className="absolute right-4 top-4 text-xl font-bold text-white/40 hover:text-white transition-colors cursor-pointer"
        >
          ✕
        </button>

        <div className="mb-5">
          <p className="text-[10px] uppercase tracking-[0.28em] text-cyan-300 font-mono">
            Modalidad Virtual
          </p>
          <h2 className="mt-1 text-xl sm:text-2xl font-bold text-white">
            Nueva clase particular online
          </h2>
        </div>

        <form action={handleSubmit} className="space-y-4 text-xs sm:text-sm">
          <div>
            <label className="mb-1 block font-medium text-white/70">Título de la clase</label>
            <input
              name="title"
              type="text"
              required
              defaultValue="Clase Online "
              className="w-full rounded-xl border border-white/10 bg-black/50 px-3 py-2.5 text-white focus:border-cyan-400 focus:outline-none"
            />
          </div>

          <div>
            <label className="mb-1 block font-medium text-white/70">Categoría</label>
            <CategorySelect initialCategories={categories} />
          </div>

          <div>
            <label className="mb-1 block font-medium text-white/70">Link de reunión (Zoom / Meet)</label>
            <input
              name="location"
              type="text"
              required
              placeholder="https://zoom.us/j/..."
              className="w-full rounded-xl border border-white/10 bg-black/50 px-3 py-2.5 text-white focus:border-cyan-400 focus:outline-none"
            />
          </div>

          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className="mb-1 block font-medium text-white/70">Inicio</label>
              <input
                name="start_time"
                type="datetime-local"
                required
                min={nowIso}
                value={startValue}
                onChange={(e) => setStartValue(e.target.value)}
                className="w-full rounded-xl border border-white/10 bg-black/50 px-3 py-2 text-white focus:border-cyan-400 focus:outline-none [color-scheme:dark]"
              />
            </div>
            <div>
              <label className="mb-1 block font-medium text-white/70">Término</label>
              <input
                name="end_time"
                type="datetime-local"
                required
                min={startValue || nowIso}
                className="w-full rounded-xl border border-white/10 bg-black/50 px-3 py-2 text-white focus:border-cyan-400 focus:outline-none [color-scheme:dark]"
              />
            </div>
          </div>

          <input type="hidden" name="status" value="published" />

          <div className="flex justify-end gap-2.5 pt-3 border-t border-white/10">
            <button
              type="button"
              onClick={() => setIsOpen(false)}
              className="rounded-xl border border-white/10 bg-white/5 px-4 py-2 text-xs font-medium text-white/70 hover:bg-white/10 cursor-pointer"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="rounded-xl bg-cyan-500 px-5 py-2 text-xs font-bold text-black shadow-lg shadow-cyan-500/20 hover:bg-cyan-400 disabled:opacity-50 cursor-pointer"
            >
              {isSubmitting ? "Publicando..." : "Publicar clase online"}
            </button>
          </div>
        </form>
      </div>
    </div>
  ) : null;

  return (
    <>
      <button
        type="button"
        onClick={() => setIsOpen(true)}
        className="w-full sm:w-auto bg-cyan-500/15 border border-cyan-400/40 text-cyan-200 px-3.5 py-2.5 rounded-xl text-[11px] font-bold uppercase tracking-[0.16em] shadow-lg transition-all hover:bg-cyan-500/25 active:scale-95 text-center cursor-pointer"
      >
        + Clase Particular Online
      </button>
      {mounted && modalContent && createPortal(modalContent, document.body)}
    </>
  );
}

