                          </Link>
                          <form action={deleteEvent}>
                            <input type="hidden" name="event_id" value={event.id} />
                            <button
                              type="submit"
                              className="font-medium text-red-400 hover:underline text-xs bg-transparent border-none cursor-pointer"
                            >
                              Eliminar
                            </button>
                          </form>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}

