import { createClient } from "@/lib/supabase/server";
import Link from "next/link";
import ClasesTomadasCarousel from "./UserEventsCarousel";
import ClassesCarousel from "./components/ClassesCarousel";
import { EventAssembler } from "@/lib/infrastructure/assemblers/EventAssembler";

export default async function MiCuentaPage() {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return null;

  const nowIso = new Date().toISOString();

  const { data: clasesActivas } = await supabase
    .from("attendances")
    .select("id, event_id, events!inner(title, start_time, end_time, location, capacity, categories(name, color))")
    .eq("user_id", user.id)
    .eq("status", "registered")
    .gte("events.end_time", nowIso)
    .order("events(start_time)", { ascending: true });

  const { data: clasesDisponiblesRaw } = await supabase
    .from("events")
    .select("id, title, description, start_time, end_time, location, capacity, categories(name, color)")
    .eq("status", "published")
    .gte("start_time", nowIso)
    .order("start_time", { ascending: true });

  const { data: conteos } = await supabase
    .from("event_attendance_counts")
    .select("event_id, total_registered");

  const { data: misInscripcionesRaw } = await supabase
    .from("attendances")
    .select("event_id")
    .eq("user_id", user.id)
    .eq("status", "registered");

  const { data: userReviewsRaw } = await supabase
    .from("event_reviews")
    .select("event_id, rating, comment, recommendation")
    .eq("user_id", user.id);

  const misInscripciones = new Set((misInscripcionesRaw ?? []).map((row: any) => row.event_id));
  const conteoPorEvento = new Map((conteos ?? []).map((row: any) => [row.event_id, row.total_registered]));
  const reviewsByEvent = new Map(
    (userReviewsRaw ?? []).map((row: { event_id: string; rating: number; comment: string | null; recommendation: string | null }) => [
      row.event_id,
      {
        rating: row.rating,
        comment: row.comment,
        recommendation: row.recommendation,
      },
    ])
  );

  const proximaClase = clasesActivas?.[0]?.events as unknown as { title: string; start_time: string } | undefined;
  const countActivas = clasesActivas?.length || 0;

  const clasesDisponibles = EventAssembler.toCards(
    ((clasesDisponiblesRaw ?? []) as unknown as Array<{
      id: string;
      title: string;
      description: string | null;
      start_time: string;
      end_time: string;
      location: string | null;
      capacity: number | null;
      status?: "draft" | "published" | "cancelled";
      categories?: { name: string; color: string | null } | null;
    }>).map((evento) => ({
      ...evento,
      status: (evento.status ?? "published") as "draft" | "published" | "cancelled",
    }))
  ).map((evento) => ({
    id: evento.id,
    title: evento.title,
    description: evento.description,
    start_time: evento.start_time,
    end_time: evento.end_time,
    location: evento.location,
    capacity: evento.capacity,
    registeredCount: conteoPorEvento.get(evento.id) ?? 0,
    isRegistered: misInscripciones.has(evento.id),
    categoryName: evento.categoryName,
    categoryColor: evento.categoryColor,
  }));

  const clasesTomadas = (clasesActivas ?? [])
    .filter((row: any) => row.events && new Date(row.events.end_time).getTime() < Date.now())
    .map((row: any) => {
      const review = reviewsByEvent.get(row.event_id);
      return {
        attendanceId: row.id,
        eventId: row.event_id,
        title: row.events.title,
        start_time: row.events.start_time,
        location: row.events.location,
        categoryName: row.events.categories?.name ?? null,
        categoryColor: row.events.categories?.color ?? null,
        status: "completed",
        reviewRating: review?.rating ?? null,
        reviewComment: review?.comment ?? null,
        reviewRecommendation: review?.recommendation ?? null,
      };
    });

  return (
    <div className="max-w-5xl mx-auto p-4 md:p-8">
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-white" style={{ fontFamily: "var(--font-serif)" }}>
          Resumen
        </h1>
        <p className="text-white/50 text-sm mt-1">Tu actividad en Like a Shh</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        <div className="p-6 bg-white/5 border border-white/10 rounded-2xl backdrop-blur-xl">
          <span className="text-xs uppercase tracking-wider text-white/50 block mb-2 font-semibold">
            Próxima Clase
          </span>
          {proximaClase ? (
            <div>
              <p className="text-lg font-bold text-white">{proximaClase.title}</p>
              <p className="text-xs text-gold mt-1">
                {new Date(proximaClase.start_time).toLocaleDateString("es-CL", {
                  weekday: "long",
                  day: "numeric",
                  month: "short",
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </p>
            </div>
          ) : (
            <div>
              <p className="text-sm text-white/60">No tienes clases próximas.</p>
              <Link href="/mi-cuenta/explorar" className="text-xs text-gold hover:underline mt-1 inline-block">
                Explorar actividades
              </Link>
            </div>
          )}
        </div>

        <div className="p-6 bg-white/5 border border-white/10 rounded-2xl backdrop-blur-xl flex flex-col items-center justify-center">
          <span className="text-4xl font-bold text-gold font-mono">{countActivas}</span>
          <span className="text-xs uppercase tracking-wider text-white/60 mt-1 font-semibold">
            {countActivas === 1 ? "Clase Activa" : "Clases Activas"}
          </span>
        </div>
      </div>

      <div className="flex flex-wrap gap-3 mb-8">
        <Link
          href="/mi-cuenta/explorar"
          className="bg-gold text-black text-xs font-bold px-6 py-3 rounded-full hover:bg-gold-light transition-all"
        >
          EXPLORAR ACTIVIDADES
        </Link>
        <Link
          href="/mi-cuenta/clases"
          className="bg-gold text-black text-xs font-bold px-6 py-3 rounded-full hover:bg-gold-light transition-all"
        >
          VER MIS CLASES
        </Link>
      </div>

      <ClassesCarousel
        title="Clases y Workshops Disponibles"
        subtitle="Selecciona tus próximas sesiones con el profesor"
        items={clasesDisponibles}
      />

      <ClasesTomadasCarousel clases={clasesTomadas} />
    </div>
  );
}

"use server";

import { z } from "zod";
import { createClient } from "@/lib/supabase/server";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { headers } from "next/headers";

const profileSchema = z.object({
  full_name: z.string().min(2, "El nombre debe tener al menos 2 caracteres"),
  phone: z.string().optional(),
  birth_date: z.string().optional(),
  gender: z.enum(["femenino", "masculino", "no_binario", "prefiero_no_decir", "otro"]).optional(),
});

// 1. Rectificación de datos personales
export async function actualizarPerfil(formData: FormData) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect("/login");

  const parsed = profileSchema.safeParse({
    full_name: formData.get("full_name"),
    phone: formData.get("phone") || undefined,
    birth_date: formData.get("birth_date") || undefined,
    gender: formData.get("gender") || undefined,
  });

  if (!parsed.success) {
    return { error: parsed.error.issues[0].message };
  }

  const { error } = await supabase
    .from("profiles")
    .update({
      full_name: parsed.data.full_name,
      phone: parsed.data.phone || null,
      birth_date: parsed.data.birth_date || null,
      gender: parsed.data.gender || "prefiero_no_decir",
      updated_at: new Date().toISOString(),
    })
    .eq("id", user.id);

  if (error) return { error: error.message };

  revalidatePath("/mi-cuenta");
  revalidatePath("/mi-cuenta/perfil");
  return { success: true };
}

// 2. Anonimización de datos personales (Ley 21.719)
export async function anonimizarDatos() {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect("/login");

  const anonId = `anon_${user.id.slice(0, 8)}`;

  // Se disocian los datos personales del perfil sin romper métricas agregadas
  const { error } = await supabase
    .from("profiles")
    .update({
      full_name: "Usuario Anonimizado",
      phone: null,
      birth_date: null,
      gender: "prefiero_no_decir",
      is_anonymized: true,
      updated_at: new Date().toISOString(),
    })
    .eq("id", user.id);

  if (error) return { error: error.message };

  const headerList = await headers();
  await supabase.from("consent_logs").insert({
    user_id: user.id,
    consent_type: "solicitud_anonimizacion_ley21719",
    accepted: true,
    policy_version: "politica-privacidad-v2-ley21719-2026",
    ip_address: headerList.get("x-forwarded-for") ?? "unknown",
  });

  revalidatePath("/mi-cuenta");
  return { success: true };
}

// 3. Derecho de Supresión Total (Eliminación de cuenta y datos)
export async function eliminarCuentaTotal() {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect("/login");

  // Registro de consentimiento antes de eliminar registros
  const headerList = await headers();
  await supabase.from("consent_logs").insert({
    user_id: user.id,
    consent_type: "supresion_definitiva_cuenta",
    accepted: true,
    policy_version: "politica-privacidad-v2-ley21719-2026",
    ip_address: headerList.get("x-forwarded-for") ?? "unknown",
  });

  // Limpieza de inscripciones y perfil (Auth cascade o RPC en Supabase)
  await supabase.from("attendances").delete().eq("user_id", user.id);
  await supabase.from("profiles").delete().eq("id", user.id);
  await supabase.auth.signOut();

  redirect("/?cuenta_eliminada=1");
}

type CommandResult = { success: boolean; data?: Record<string, unknown>; error?: string };

type AuditLogPayload = {
  actor_id: string | null;
  action: string;
  metadata: Record<string, unknown>;
};

type Command = {
  execute: () => Promise<CommandResult>;
  actionName: string;
};

export class CommandInvoker {
  constructor(
    private readonly supabaseClient: any
  ) {}

  public async execute(command: Command): Promise<CommandResult> {
    const result = await command.execute();

    if (!result.success) {
      return result;
    }

    const {
      data: { user },
    } = await this.supabaseClient.auth.getUser();

    await this.supabaseClient.from("audit_log").insert({
      actor_id: user?.id ?? null,
      action: command.actionName,
      metadata: result.data ?? {},
    });

    return result;
  }
}

export type EventRecord = {
  id: string;
  title: string;
  description: string | null;
  start_time: string;
  end_time: string;
  location: string | null;
  capacity: number | null;
  status: "draft" | "published" | "cancelled";
  category_id: string | null;
  categories?: { id: string; name: string; color: string | null } | null;
  image_url?: string | null;
};

export class EventQueryBuilder {
  private readonly query: any;
  private publishedOnly = false;
  private futureOnly = false;
  private category: string | null = null;
  private ascending = true;

  constructor(supabaseClient: any) {
    this.query = supabaseClient
      .from("events")
      .select(
        "id, title, description, start_time, end_time, location, capacity, status, category_id, categories(id, name, color), image_url"
      );
  }

  public static from(supabaseClient: any): EventQueryBuilder {
    return new EventQueryBuilder(supabaseClient);
  }

  public soloPublicados(): this {
    this.publishedOnly = true;
    return this;
  }

  public soloFuturos(): this {
    this.futureOnly = true;
    return this;
  }

  public porCategoria(categoria: string): this {
    this.category = categoria;
    return this;
  }

  public ordenarCronologico(): this {
    this.ascending = true;
    return this;
  }

  public async execute(): Promise<EventRecord[]> {
    let query: any = this.query;

    if (this.publishedOnly) {
      query = query.eq("status", "published");
    }

    if (this.futureOnly) {
      query = query.gte("start_time", new Date().toISOString());
    }

    if (this.category) {
      query = query.eq("category_id", this.category);
    }

    const { data, error } = await query.order("start_time", { ascending: this.ascending });

    if (error) {
      return [];
    }

    return (data ?? []) as EventRecord[];
  }
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";

describe("rate-limit utilities", () => {
  let consoleWarnSpy: any;
  let consoleErrorSpy: any;

  beforeEach(() => {
    vi.resetModules();
    vi.unstubAllEnvs();
    consoleWarnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    consoleErrorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
    delete process.env.UPSTASH_REDIS_REST_URL;
    delete process.env.UPSTASH_REDIS_REST_TOKEN;
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllEnvs();
    delete process.env.UPSTASH_REDIS_REST_URL;
    delete process.env.UPSTASH_REDIS_REST_TOKEN;
  });

  it("should block access in production when Upstash is not configured", async () => {
    vi.stubEnv("NODE_ENV", "production");

    const { checkLoginRateLimit } = await import("./rate-limit");
    const result = await checkLoginRateLimit("127.0.0.1");

    expect(result).toEqual({ success: false, retryAfter: 60 });
    expect(consoleErrorSpy).toHaveBeenCalledWith(
      expect.stringContaining("[rate-limit] Upstash no configurado en producción")
    );
  });

  it("should allow access in development when Upstash is not configured", async () => {
    vi.stubEnv("NODE_ENV", "development");

    const { checkLoginRateLimit } = await import("./rate-limit");
    const result = await checkLoginRateLimit("127.0.0.1");

    expect(result).toEqual({ success: true });
    expect(consoleWarnSpy).toHaveBeenCalledWith(
      expect.stringContaining("[rate-limit] Upstash no configurado en desarrollo")
    );
  });
});
